⫻KickLaMetta/ts:<<function>>
```ts
type Concept = {
  name: string;
  components: string[];
};

function conceptsToMarkdown(concepts: Concept[]) {
  let markdown = "";
  markdown += "# Concepts\n";
  concepts.forEach((concept, index) => {
    markdown += `## Concept ${index + 1}\n`;
    markdown += `- ${concept.name}\n`;
    markdown += concept.components.map((component) => `  - ${component}`).join("\n");
  });
  return markdown;
}

const concepts = [
  {
    name: "Concept 1",
    components: ["Component 1", "Component 2"],
  },
  {
    name: "Concept 2",
    components: ["Component 3", "Component 4"],
  },
];

const markdownOutput = conceptsToMarkdown(concepts);
console.log(markdownOutput);
```

